-- A rate is kept as versions: setting a rate for a grade and from-date that already has one keeps
-- the value it replaces as an older version and makes the new value the next version. The rate row
-- holds the newest version (the one in force) and its number, counted from 1; rate_version holds
-- every older one.
ALTER TABLE rate ADD COLUMN version INT DEFAULT 1 NOT NULL;
ALTER TABLE rate ADD CONSTRAINT rate_version_positive CHECK (version >= 1);
CREATE TABLE rate_version (
    id      BIGINT AUTO_INCREMENT PRIMARY KEY,
    rate_id BIGINT        NOT NULL REFERENCES rate (id),
    version INT           NOT NULL CHECK (version >= 1),
    pct     DECIMAL(5, 2) NOT NULL CHECK (pct >= 0),
    to_date DATE
);
CREATE UNIQUE INDEX rate_version_rate_version ON rate_version (rate_id, version);
-- A claim may now be REVIEW: opened while its due is above the sheet's review threshold in force on
-- its date, awaiting a steward's review to become OPEN. It counts nowhere and carries no number yet.
-- The review threshold is a dated setting (sheet_setting, key review-threshold); none before every
-- from-date.
ALTER TABLE claim ADD COLUMN next_status VARCHAR(16) DEFAULT 'DRAFT' NOT NULL
    CHECK (next_status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'DELETED', 'REVIEW'));
UPDATE claim SET next_status = status;
ALTER TABLE claim DROP COLUMN status;
ALTER TABLE claim ALTER COLUMN next_status RENAME TO status;

